import{_ as t,a0 as d,w as o,s as r,ao as l,I as n,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Linux 中使用 parted 對磁盤分區 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 parted 對磁盤分區 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 parted 對磁盤分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 parted 對磁盤分區 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180611 How to partition a disk in Linux","title":"如何在 Linux 中使用 parted 對磁盤分區","tag":"201806","desc":""},"relativePath":"201806/20180611 How to partition a disk in Linux.md","filePath":"[post].md"}'),u={name:"201806/20180611 How to partition a disk in Linux.md"};function c(h,s,k,f,g,b){const e=d("Link");return o(),r("div",null,[s[30]||(s[30]=l('<h1 id="如何在-linux-中使用-parted-對磁盤分區" tabindex="-1">如何在 Linux 中使用 parted 對磁盤分區 <a class="header-anchor" href="#如何在-linux-中使用-parted-對磁盤分區" aria-label="Permalink to “如何在 Linux 中使用 parted 對磁盤分區”">​</a></h1><blockquote><p>學習如何在 Linux 中使用 parted 命令來對存儲設備分區。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus-storage.png?itok=95-zvHYl" alt=""></p><p>在 Linux 中創建和刪除分區是一種常見的操作，因為存儲設備（如硬盤驅動器和 USB 驅動器）在使用之前必須以某種方式進行結構化。在大多數情況下，大型存儲設備被分為稱為<ruby>分區<rt>partition</rt></ruby>的獨立部分。分區操作允許您將硬盤分割成獨立的部分，每個部分都像是一個硬盤驅動器一樣。如果您運行多個操作系統，那麼分區是非常有用的。</p><p>在 Linux 中有許多強大的工具可以創建、刪除和操作磁盤分區。在本文中，我將解釋如何使用 <code>parted</code> 命令，這對於大型磁盤設備和許多磁盤分區尤其有用。<code>parted</code> 與更常見的 <code>fdisk</code> 和 <code>cfdisk</code> 命令之間的區別包括:</p>',5)),n("ul",null,[n("li",null,[s[1]||(s[1]=n("strong",null,"GPT 格式：",-1)),s[2]||(s[2]=n("code",null,"parted",-1)),s[3]||(s[3]=a(" 命令可以創建全局惟一的標識符分區表 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/GUID_Partition_Table"},{default:p(()=>[...s[0]||(s[0]=[a("GPT",-1)])]),_:1}),s[4]||(s[4]=a("，而 ",-1)),s[5]||(s[5]=n("code",null,"fdisk",-1)),s[6]||(s[6]=a(" 和 ",-1)),s[7]||(s[7]=n("code",null,"cfdisk",-1)),s[8]||(s[8]=a(" 則僅限於 DOS 分區表。",-1))]),s[13]||(s[13]=n("li",null,[n("strong",null,"更大的磁盤："),a(" DOS 分區表可以格式化最多 2TB 的磁盤空間，儘管在某些情況下最多可以達到 16TB。然而，一個 GPT 分區表可以處理最多 8ZiB 的空間。")],-1)),s[14]||(s[14]=n("li",null,[n("strong",null,"更多的分區："),a(" 使用主分區和擴展分區，DOS 分區表只允許 16 個分區。在 GPT 中，默認情況下您可以得到 128 個分區，並且可以選擇更多的分區。")],-1)),n("li",null,[s[10]||(s[10]=n("strong",null,"可靠性：",-1)),s[11]||(s[11]=a(" 在 DOS 分區表中，只保存了一份分區表備份，在 GPT 中保留了兩份分區表的備份（在磁盤的起始和結束部分），同時 GPT 還使用了 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Cyclic_redundancy_check"},{default:p(()=>[...s[9]||(s[9]=[a("CRC",-1)])]),_:1}),s[12]||(s[12]=a(" 校驗和來檢查分區表的完整性，在 DOS 分區中並沒有實現。",-1))])]),s[31]||(s[31]=l(`<p>由於現在的磁盤更大，需要更靈活地使用它們，建議使用 <code>parted</code> 來處理磁盤分區。大多數時候，磁盤分區表是作為操作系統安裝過程的一部分創建的。在向現有系統添加存儲設備時，直接使用 <code>parted</code> 命令非常有用。</p><h3 id="嘗試一下-parted" tabindex="-1">嘗試一下 parted <a class="header-anchor" href="#嘗試一下-parted" aria-label="Permalink to “嘗試一下 parted”">​</a></h3><p>下面解釋了使用 <code>parted</code> 命令對存儲設備進行分區的過程。為了嘗試這些步驟，我強烈建議使用一塊全新的存儲設備或一種您不介意將其內容刪除的設備。</p><h4 id="_1、列出分區" tabindex="-1">1、列出分區 <a class="header-anchor" href="#_1、列出分區" aria-label="Permalink to “1、列出分區”">​</a></h4><p>使用 <code>parted -l</code> 來標識你要進行分區的設備。一般來説，第一個硬盤 （<code>/dev/sda</code> 或 <code>/dev/vda</code> ）保存着操作系統， 因此要尋找另一個磁盤，以找到你想要分區的磁盤 (例如，<code>/dev/sdb</code>、<code>/dev/sdc</code>、 <code>/dev/vdb </code>、<code>/dev/vdc</code> 等)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo parted -l</span></span>
<span class="line"><span>[sudo] password for daniel: </span></span>
<span class="line"><span>Model: ATA RevuAhn_850X1TU5 (scsi)</span></span>
<span class="line"><span>Disk /dev/vdc: 512GB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: msdos</span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End    Size   Type     File system  Flags</span></span>
<span class="line"><span> 1      1049kB  525MB  524MB  primary  ext4         boot</span></span>
<span class="line"><span> 2      525MB   512GB  512GB  primary               lvm</span></span></code></pre></div><h4 id="_2、打開存儲設備" tabindex="-1">2、打開存儲設備 <a class="header-anchor" href="#_2、打開存儲設備" aria-label="Permalink to “2、打開存儲設備”">​</a></h4><p>使用 <code>parted</code> 選中您要分區的設備。在這裏例子中，是虛擬系統上的第三個磁盤（<code>/dev/vdc</code>）。指明你要使用哪一個設備非常重要。 如果你僅僅輸入了 <code>parted</code> 命令而沒有指定設備名字， 它會<strong>隨機</strong>選擇一個設備進行操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo parted /dev/vdc</span></span>
<span class="line"><span>GNU Parted 3.2</span></span>
<span class="line"><span>Using /dev/vdc</span></span>
<span class="line"><span>Welcome to GNU Parted! Type &#39;help&#39; to view a list of commands.</span></span>
<span class="line"><span>(parted)</span></span></code></pre></div><h4 id="_3、-設定分區表" tabindex="-1">3、 設定分區表 <a class="header-anchor" href="#_3、-設定分區表" aria-label="Permalink to “3、 設定分區表”">​</a></h4><p>設置分區表為 GPT ，然後輸入 <code>Yes</code> 開始執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) mklabel gpt </span></span>
<span class="line"><span>Warning: the existing disk label on /dev/vdc will be destroyed </span></span>
<span class="line"><span>and all data on this disk will be lost. Do you want to continue? </span></span>
<span class="line"><span>Yes/No? Yes</span></span></code></pre></div><p><code>mklabel</code> 和 <code>mktable</code> 命令用於相同的目的（在存儲設備上創建分區表）。支持的分區表有：aix、amiga、bsd、dvh、gpt、mac、ms-dos、pc98、sun 和 loop。記住 <code>mklabel</code> 不會創建一個分區，而是創建一個分區表。</p><h4 id="_4、-檢查分區表" tabindex="-1">4、 檢查分區表 <a class="header-anchor" href="#_4、-檢查分區表" aria-label="Permalink to “4、 檢查分區表”">​</a></h4><p>查看存儲設備信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) print </span></span>
<span class="line"><span>Model: Virtio Block Device (virtblk) </span></span>
<span class="line"><span>Disk /dev/vdc: 1396MB </span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B </span></span>
<span class="line"><span>Partition Table: gpt </span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span>Number Start End Size File system Name Flags</span></span></code></pre></div><h4 id="_5、-獲取幫助" tabindex="-1">5、 獲取幫助 <a class="header-anchor" href="#_5、-獲取幫助" aria-label="Permalink to “5、 獲取幫助”">​</a></h4><p>為了知道如何去創建一個新分區，輸入： <code>(parted) help mkpart</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) help mkpart </span></span>
<span class="line"><span>  mkpart PART-TYPE [FS-TYPE] START END     make a partition</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        PART-TYPE is one of: primary, logical, extended</span></span>
<span class="line"><span>        FS-TYPE is one of: btrfs, nilfs2, ext4, ext3, ext2, fat32, fat16, hfsx, hfs+, hfs, jfs, swsusp,</span></span>
<span class="line"><span>        linux-swap(v1), linux-swap(v0), ntfs, reiserfs, hp-ufs, sun-ufs, xfs, apfs2, apfs1, asfs, amufs5,</span></span>
<span class="line"><span>        amufs4, amufs3, amufs2, amufs1, amufs0, amufs, affs7, affs6, affs5, affs4, affs3, affs2, affs1,</span></span>
<span class="line"><span>        affs0, linux-swap, linux-swap(new), linux-swap(old)</span></span>
<span class="line"><span>        START and END are disk locations, such as 4GB or 10%.  Negative values count from the end of the</span></span>
<span class="line"><span>        disk.  For example, -1s specifies exactly the last sector.</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        &#39;mkpart&#39; makes a partition without creating a new file system on the partition.  FS-TYPE may be</span></span>
<span class="line"><span>        specified to set an appropriate partition ID.</span></span></code></pre></div><h4 id="_6、-創建分區" tabindex="-1">6、 創建分區 <a class="header-anchor" href="#_6、-創建分區" aria-label="Permalink to “6、 創建分區”">​</a></h4><p>為了創建一個新分區（在這個例子中，分區 0 有 1396MB），輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) mkpart primary 0 1396MB </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Warning: The resulting partition is not properly aligned for best performance </span></span>
<span class="line"><span>Ignore/Cancel? I </span></span>
<span class="line"><span></span></span>
<span class="line"><span>(parted) print </span></span>
<span class="line"><span>Model: Virtio Block Device (virtblk) </span></span>
<span class="line"><span>Disk /dev/vdc: 1396MB </span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B </span></span>
<span class="line"><span>Partition Table: gpt </span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span>Number Start   End     Size    File system Name Flags </span></span>
<span class="line"><span>1      17.4kB  1396MB  1396MB  primary</span></span></code></pre></div><p>文件系統類型（<code>fstype</code>）並不是在 <code>/dev/vdc1</code>上創建 ext4 文件系統。 DOS 分區表的分區類型是<ruby>主分區<rt>primary</rt></ruby>、<ruby>邏輯分區<rt>logical</rt></ruby>和<ruby>擴展分區<rt>extended</rt></ruby>。 在 GPT 分區表中，分區類型用作分區名稱。 在 GPT 下必須提供分區名稱；在上例中，<code>primary</code> 是分區名稱，而不是分區類型。</p><h4 id="_7、-保存退出" tabindex="-1">7、 保存退出 <a class="header-anchor" href="#_7、-保存退出" aria-label="Permalink to “7、 保存退出”">​</a></h4><p>當你退出 <code>parted</code> 時，修改會自動保存。退出請輸入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) quit</span></span>
<span class="line"><span>Information: You may need to update /etc/fstab.</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="謹記" tabindex="-1">謹記 <a class="header-anchor" href="#謹記" aria-label="Permalink to “謹記”">​</a></h3><p>當您添加新的存儲設備時，請確保在開始更改其分區表之前確定正確的磁盤。如果您錯誤地更改了包含計算機操作系統的磁盤分區，會使您的系統無法啓動。</p><hr>`,29)),n("p",null,[s[16]||(s[16]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/18/6/how-partition-disk-linux"},{default:p(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/18/6/how-partition-disk-linux",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/daniel-oh"},{default:p(()=>[...s[17]||(s[17]=[a("Daniel Oh",-1)])]),_:1}),s[22]||(s[22]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 譯者：",-1)),i(e,{href:"https://github.com/amwps290"},{default:p(()=>[...s[19]||(s[19]=[a("amwps290",-1)])]),_:1}),s[24]||(s[24]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[26]||(s[26]=[a("Linux中國",-1)])]),_:1}),s[29]||(s[29]=a(" 榮譽推出",-1))])])}const y=t(u,[["render",c]]);export{T as __pageData,y as default};
